def main():
    figs_p, tl_p, wr_p = (os.path.join(ROOT, 'data', f) for f in ('figures.json', 'timeline.json', 'writings.json'))
    figs = [f for f in json.load(open(figs_p, encoding='utf-8')) if int(f['id'][4:]) < FIRST_FIG]
    tl = [e for e in json.load(open(tl_p, encoding='utf-8')) if e['era'] != ERA]
    wr = json.load(open(wr_p, encoding='utf-8'))
    key = {}
    for i, f in enumerate(FIG):
        key[f[0]] = 'FIG-%04d' % (FIRST_FIG + i)
    ev_rows = []
    start = max(int(e['id'][3:]) for e in tl) + 1
    for i, e in enumerate(sorted(EV, key=lambda e: e[3])):
        (name, a, b, iso, iso_to, said, basis, places, theatre, summary, who, writ, src) = e
        ids = [key.get(w.strip(), w.strip()) for w in who.split('|') if w.strip()]
        ev_rows.append({'id': 'EV-%04d' % (start + i), 'name': name, 'date_from': a, 'date_to': b, 'date_iso': iso, 'date_iso_to': iso_to,
                        'date_text': said, 'date_basis': basis, 'places': places, 'theatre': theatre, 'era': ERA, 'summary': summary,
                        'figures': ' | '.join(ids), 'writings': writ, 'sources': src})
    for i, f in enumerate(FIG):
        (k, name, aliases, born, died, bt, dt, bp, dp, places, eras, roles, ach, notes) = f
        fid = key[k]
        evs = [e['id'] for e in ev_rows if fid in e['figures'].split(' | ')]
        figs.append({'id': fid, 'name': name, 'aliases': aliases, 'born_year': born, 'died_year': died, 'born_text': bt, 'died_text': dt,
                     'born_place': bp, 'died_place': dp, 'places': places, 'eras': eras, 'roles': roles, 'achievements': ach,
                     'relations': '', 'writings': '', 'events': ' | '.join(evs), 'sources': wp(name), 'notes': notes})
    # FIRST CLEMENT'S OWN ROWS name the event that names them (check-history-db: links both ways).
    for fid in ('FIG-0003',):
        f = next(x for x in figs if x['id'] == fid)
        mine = [e['id'] for e in ev_rows if fid in e['figures'].split(' | ')]
        old = [v.strip() for v in f['events'].split('|') if v.strip() and not any(v.strip() == e['id'] for e in ev_rows)]
        f['events'] = ' | '.join(old + mine)
    for w in wr:
        mine = [e['id'] for e in ev_rows if w['id'] in e['writings'].split(' | ')]
        old = [v.strip() for v in w['events'].split('|') if v.strip() and int(v.strip()[3:]) < start]
        w['events'] = ' | '.join(old + mine)
    rows = sorted(tl + ev_rows, key=lambda e: e['date_iso'])

    def dump(p, rows):
        with open(p, 'w', encoding='utf-8') as fh:
            fh.write('[\n' + ',\n'.join(json.dumps(r, ensure_ascii=False) for r in rows) + '\n]\n')
    dump(figs_p, figs)
    dump(tl_p, rows)
    dump(wr_p, wr)
    print(len(FIG), 'figures,', len(ev_rows), 'church history events')


if __name__ == '__main__':
    main()
